            dd_[8] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)]);
            dd_[9] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
