            dd_[12] += dfac * (dm[(j0+1)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)]);
            dd_[13] += dfac * (dm[(j0+1)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)]);
            dd_[14] += dfac * (dm[(j0+1)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)]);
            dd_[15] += dfac * (dm[(j0+1)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+0)]);
            dd_[16] += dfac * (dm[(j0+1)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+1)]);
            dd_[17] += dfac * (dm[(j0+1)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)]);
