                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[26];
                    fyi = ai2 * giy - 1 * G[24];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[31] - (1) * G[19];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[40];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[36];
                    fzk = ak2 * G[45];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[23];
                    Ix = G[0];
                    Iy = G[24];
                    Iz = G[40];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[6];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[25];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[30] - (1) * G[18];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[41];
                    fzi = ai2 * giz - 1 * G[39];
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[37];
                    fzk = ak2 * G[46];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[24];
                    Ix = G[1];
                    Iy = G[18];
                    Iz = G[45];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[2];
                    fxi = ai2 * gix - 1 * G[0];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[7];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[19];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[24];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[46];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[42];
                    fzk = ak2 * G[51] - (1) * G[39];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[25];
                    Ix = G[0];
                    Iy = G[19];
                    Iz = G[45];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[6];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[20];
                    fyi = ai2 * giy - 1 * G[18];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[25];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[46];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[42];
                    fzk = ak2 * G[51] - (1) * G[39];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[26];
                    Ix = G[0];
                    Iy = G[18];
                    Iz = G[46];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[6];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[19];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[24];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[47];
                    fzi = ai2 * giz - 1 * G[45];
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[43];
                    fzk = ak2 * G[52] - (1) * G[40];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
    }
    // every thread of the block shares ish/jsh, so the bra half reduces inside
    // the warp before it reaches the six atomics
#pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        v_ix += __shfl_down_sync(0xffffffff, v_ix, off);
        v_iy += __shfl_down_sync(0xffffffff, v_iy, off);
        v_iz += __shfl_down_sync(0xffffffff, v_iz, off);
        v_jx += __shfl_down_sync(0xffffffff, v_jx, off);
        v_jy += __shfl_down_sync(0xffffffff, v_jy, off);
        v_jz += __shfl_down_sync(0xffffffff, v_jz, off);
    }
    if ((thread_id & 31) == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, v_ix);
        atomicAdd(ejk+ia*3+1, v_iy);
        atomicAdd(ejk+ia*3+2, v_iz);
        atomicAdd(ejk+ja*3+0, v_jx);
        atomicAdd(ejk+ja*3+1, v_jy);
        atomicAdd(ejk+ja*3+2, v_jz);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


