    __syncthreads();
    reduce[0*threads] = v_ix;  reduce[1*threads] = v_iy;
    reduce[2*threads] = v_iz;  reduce[3*threads] = v_jx;
    reduce[4*threads] = v_jy;  reduce[5*threads] = v_jz;
    for (int i = 64; i > 0; i >>= 1) {
        __syncthreads();
        if (thread_id < i && thread_id + i < threads) {
#pragma unroll
            for (int n = 0; n < 6; ++n) {
                reduce[n*threads] += reduce[n*threads+i];
            }
        }
    }
    if (thread_id == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, reduce[0*threads]);
        atomicAdd(ejk+ia*3+1, reduce[1*threads]);
        atomicAdd(ejk+ia*3+2, reduce[2*threads]);
        atomicAdd(ejk+ja*3+0, reduce[3*threads]);
        atomicAdd(ejk+ja*3+1, reduce[4*threads]);
        atomicAdd(ejk+ja*3+2, reduce[5*threads]);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (2000) reg : 6 gout, g_size 8, 2 roots, one thread per quartet
extern "C" __global__ void __launch_bounds__(256, 1)
ejk_2000(EARGS)
{
    constexpr int NROOTS = 2;
    constexpr int GSZ = 8;
    constexpr int threads = 256;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36], s_ai2[36], s_aj2[36];
    __shared__ int ntasks, pair_ij, ish, jsh;
    __shared__ double ri[3], rjri[3];
    int thread_id = threadIdx.x;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    int do_j = j_factor != 0.;
    int do_k = k_factor != 0.;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = thread_id; task_id < ntasks; task_id += threads) {
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (ish == jsh) fac_sym *= .5;
        if (ksh == lsh) fac_sym *= .5;
        if (bas_ij == bas_kl) fac_sym *= .5;
        const double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
        const double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
        const double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
        const double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double rlrk0 = rl[0]-rk[0], rlrk1 = rl[1]-rk[1], rlrk2 = rl[2]-rk[2];
        double rr_kl = rlrk0*rlrk0 + rlrk1*rlrk1 + rlrk2*rlrk2;
        double dd_[6];
        int i0 = ao_loc[ish], j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
        double dfac;
        #pragma unroll
        for (int n = 0; n < 6; ++n) dd_[n] = 0.;
        if (do_k) {
            dfac = fac_sym * k_factor;
            dd_[0] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[1] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[2] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[3] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[4] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[5] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
        }
        if (do_j) {
            dfac = fac_sym * j_factor;
            dd_[0] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+0)]);
            dd_[1] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+1)]);
            dd_[2] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+2)]);
            dd_[3] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+3)]);
            dd_[4] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+4)]);
            dd_[5] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+5)]);
        }
        double v_kx = 0, v_ky = 0, v_kz = 0, v_lx = 0, v_ly = 0, v_lz = 0;
        double G[3*GSZ];
        double rw[2*NROOTS];
        double dd, Ix, Iy, Iz, pxy, pxz, pyz;
        double gix, giy, giz;
        double fxi, fyi, fzi, fxj, fyj, fzj, fxk, fyk, fzk;
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            double ak = expk[klp/lprim];
            double al = expl[klp%lprim];
            double akl = ak + al;
            double iakl = 1. / akl;
            double al_akl = al * iakl;
            double ak2 = ak + ak;
            double ckcl = ck[klp/lprim] * cl[klp%lprim]
                        * exp(-ak * al_akl * rr_kl);
            double xqc = rlrk0 * al_akl, yqc = rlrk1 * al_akl, zqc = rlrk2 * al_akl;
            double xkl = rk[0] + xqc, ykl = rk[1] + yqc, zkl = rk[2] + zqc;
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double aj_aij = s_ajaij[ijp];
                double ai2 = s_ai2[ijp], aj2 = s_aj2[ijp];
                // inv_om2 = 0 is the full-range operator; 1/omega^2 the
                // long-range (erf) one -- scaling the Rys argument and roots
                // by w^2/(w^2+theta) is exactly this one fma.
                double inv_s = rsqrt(fma(aij * akl, inv_om2, aij + akl));
                double inv_s2 = inv_s * inv_s;
                double xpa = rjri0 * aj_aij;
                double ypa = rjri1 * aj_aij;
                double zpa = rjri2 * aj_aij;
                double xpq = s_xij[ijp] - xkl;
                double ypq = s_yij[ijp] - ykl;
                double zpq = s_zij[ijp] - zkl;
                double rr = xpq*xpq + ypq*ypq + zpq*zpq;
                G[0]   = ckcl;
                G[GSZ] = s_cicj[ijp] * iaij * iakl * inv_s * coef0;
                ejk_roots_reg<NROOTS>(aij * akl * inv_s2 * rr, rw, tab);
                // deliberately not unrolled: unrolling keeps NROOTS
                // generations of the 2D-integral array live at once and spills
                for (int irys = 0; irys < NROOTS; ++irys) {
                    double rt = rw[2*irys];
                    G[2*GSZ] = rw[2*irys+1];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    double s0, s1, s2;
                    (void)b10; (void)b00; (void)b01; (void)s2;
                    {
                        double c0x = xpa - rt_aij * xpq;
                        double cpx = xqc + rt_akl * xpq;
                        double xjxi = rjri0, xlxk = rlrk0;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[0];
                        s1 = c0x * s0;
                        G[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[2] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[3] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[0];
                        s1 = cpx * s0;
                        G[4] = s1;
                        s0 = G[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[0];
                        G[5] = s1;
                        s0 = G[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[1];
                        G[6] = s1;
                        s0 = G[3];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[2];
                        G[7] = s1;
                    }
                    {
                        double c0x = ypa - rt_aij * ypq;
                        double cpx = yqc + rt_akl * ypq;
                        double xjxi = rjri1, xlxk = rlrk1;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[8];
                        s1 = c0x * s0;
                        G[9] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[10] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[11] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[8];
                        s1 = cpx * s0;
                        G[12] = s1;
                        s0 = G[9];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[8];
                        G[13] = s1;
                        s0 = G[10];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[9];
                        G[14] = s1;
                        s0 = G[11];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[10];
                        G[15] = s1;
                    }
                    {
                        double c0x = zpa - rt_aij * zpq;
                        double cpx = zqc + rt_akl * zpq;
                        double xjxi = rjri2, xlxk = rlrk2;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[16];
                        s1 = c0x * s0;
                        G[17] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[18] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[19] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[16];
                        s1 = cpx * s0;
                        G[20] = s1;
                        s0 = G[17];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[16];
                        G[21] = s1;
                        s0 = G[18];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[17];
                        G[22] = s1;
                        s0 = G[19];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[18];
                        G[23] = s1;
                    }
                    dd = dd_[0];
                    Ix = G[2];
                    Iy = G[8];
                    Iz = G[16];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[3];
                    fxi = ai2 * gix - 2 * G[1];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[6];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[9];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[12];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[17];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[20];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[1];
                    Ix = G[1];
                    Iy = G[9];
                    Iz = G[16];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[2];
                    fxi = ai2 * gix - 1 * G[0];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[5];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[10];
                    fyi = ai2 * giy - 1 * G[8];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[13];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[17];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[20];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[2];
                    Ix = G[1];
                    Iy = G[8];
                    Iz = G[17];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[2];
                    fxi = ai2 * gix - 1 * G[0];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[5];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[9];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[12];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[18];
                    fzi = ai2 * giz - 1 * G[16];
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[21];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[3];
                    Ix = G[0];
                    Iy = G[10];
                    Iz = G[16];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[4];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[11];
                    fyi = ai2 * giy - 2 * G[9];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[14];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[17];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[20];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[4];
                    Ix = G[0];
                    Iy = G[9];
                    Iz = G[17];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[4];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[10];
                    fyi = ai2 * giy - 1 * G[8];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[13];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[18];
                    fzi = ai2 * giz - 1 * G[16];
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[21];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[5];
                    Ix = G[0];
                    Iy = G[8];
                    Iz = G[18];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[4];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[9];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[12];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[19];
                    fzi = ai2 * giz - 2 * G[17];
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[22];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
    }
    // every thread of the block shares ish/jsh, so the bra half reduces inside
    // the warp before it reaches the six atomics
#pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        v_ix += __shfl_down_sync(0xffffffff, v_ix, off);
        v_iy += __shfl_down_sync(0xffffffff, v_iy, off);
        v_iz += __shfl_down_sync(0xffffffff, v_iz, off);
        v_jx += __shfl_down_sync(0xffffffff, v_jx, off);
        v_jy += __shfl_down_sync(0xffffffff, v_jy, off);
        v_jz += __shfl_down_sync(0xffffffff, v_jz, off);
    }
    if ((thread_id & 31) == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, v_ix);
        atomicAdd(ejk+ia*3+1, v_iy);
        atomicAdd(ejk+ia*3+2, v_iz);
        atomicAdd(ejk+ja*3+0, v_jx);
        atomicAdd(ejk+ja*3+1, v_jy);
        atomicAdd(ejk+ja*3+2, v_jz);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (2010) reg : 18 gout, g_size 12, 3 roots, one thread per quartet
extern "C" __global__ void __launch_bounds__(256, 1)
ejk_2010(EARGS)
{
    constexpr int NROOTS = 3;
    constexpr int GSZ = 12;
    constexpr int threads = 256;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36], s_ai2[36], s_aj2[36];
    __shared__ int ntasks, pair_ij, ish, jsh;
    __shared__ double ri[3], rjri[3];
    int thread_id = threadIdx.x;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    int do_j = j_factor != 0.;
    int do_k = k_factor != 0.;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = thread_id; task_id < ntasks; task_id += threads) {
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (ish == jsh) fac_sym *= .5;
        if (ksh == lsh) fac_sym *= .5;
        if (bas_ij == bas_kl) fac_sym *= .5;
        const double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
        const double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
        const double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
        const double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double rlrk0 = rl[0]-rk[0], rlrk1 = rl[1]-rk[1], rlrk2 = rl[2]-rk[2];
        double rr_kl = rlrk0*rlrk0 + rlrk1*rlrk1 + rlrk2*rlrk2;
        double dd_[18];
        int i0 = ao_loc[ish], j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
        double dfac;
        #pragma unroll
        for (int n = 0; n < 18; ++n) dd_[n] = 0.;
        if (do_k) {
            dfac = fac_sym * k_factor;
            dd_[0] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[1] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[2] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[3] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[4] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[5] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
            dd_[6] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)]);
            dd_[7] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)]);
            dd_[8] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)]);
            dd_[9] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+3)]);
            dd_[10] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+4)]);
            dd_[11] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+5)]);
            dd_[12] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+0)]);
            dd_[13] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+1)]);
            dd_[14] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+2)]);
            dd_[15] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+3)]);
            dd_[16] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+4)]);
            dd_[17] += dfac * (dm[(j0+0)*nao+(k0+2)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+2)*nao+(i0+5)]);
        }
        if (do_j) {
            dfac = fac_sym * j_factor;
            dd_[0] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+0)]);
            dd_[1] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+1)]);
            dd_[2] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+2)]);
            dd_[3] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+3)]);
            dd_[4] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+4)]);
            dd_[5] += dfac * (dm[(l0+0)*nao+(k0+0)] * dm[(j0+0)*nao+(i0+5)]);
            dd_[6] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+0)]);
            dd_[7] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+1)]);
            dd_[8] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+2)]);
            dd_[9] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+3)]);
            dd_[10] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+4)]);
            dd_[11] += dfac * (dm[(l0+0)*nao+(k0+1)] * dm[(j0+0)*nao+(i0+5)]);
            dd_[12] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+0)]);
            dd_[13] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+1)]);
            dd_[14] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+2)]);
            dd_[15] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+3)]);
            dd_[16] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+4)]);
            dd_[17] += dfac * (dm[(l0+0)*nao+(k0+2)] * dm[(j0+0)*nao+(i0+5)]);
        }
        double v_kx = 0, v_ky = 0, v_kz = 0, v_lx = 0, v_ly = 0, v_lz = 0;
        double G[3*GSZ];
        double rw[2*NROOTS];
        double dd, Ix, Iy, Iz, pxy, pxz, pyz;
        double gix, giy, giz;
        double fxi, fyi, fzi, fxj, fyj, fzj, fxk, fyk, fzk;
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            double ak = expk[klp/lprim];
            double al = expl[klp%lprim];
            double akl = ak + al;
            double iakl = 1. / akl;
            double al_akl = al * iakl;
            double ak2 = ak + ak;
            double ckcl = ck[klp/lprim] * cl[klp%lprim]
                        * exp(-ak * al_akl * rr_kl);
            double xqc = rlrk0 * al_akl, yqc = rlrk1 * al_akl, zqc = rlrk2 * al_akl;
            double xkl = rk[0] + xqc, ykl = rk[1] + yqc, zkl = rk[2] + zqc;
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double aj_aij = s_ajaij[ijp];
                double ai2 = s_ai2[ijp], aj2 = s_aj2[ijp];
                // inv_om2 = 0 is the full-range operator; 1/omega^2 the
                // long-range (erf) one -- scaling the Rys argument and roots
                // by w^2/(w^2+theta) is exactly this one fma.
                double inv_s = rsqrt(fma(aij * akl, inv_om2, aij + akl));
                double inv_s2 = inv_s * inv_s;
                double xpa = rjri0 * aj_aij;
                double ypa = rjri1 * aj_aij;
                double zpa = rjri2 * aj_aij;
                double xpq = s_xij[ijp] - xkl;
                double ypq = s_yij[ijp] - ykl;
                double zpq = s_zij[ijp] - zkl;
                double rr = xpq*xpq + ypq*ypq + zpq*zpq;
                G[0]   = ckcl;
                G[GSZ] = s_cicj[ijp] * iaij * iakl * inv_s * coef0;
                ejk_roots_reg<NROOTS>(aij * akl * inv_s2 * rr, rw, tab);
                // deliberately not unrolled: unrolling keeps NROOTS
                // generations of the 2D-integral array live at once and spills
                for (int irys = 0; irys < NROOTS; ++irys) {
                    double rt = rw[2*irys];
                    G[2*GSZ] = rw[2*irys+1];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    double s0, s1, s2;
                    (void)b10; (void)b00; (void)b01; (void)s2;
                    {
                        double c0x = xpa - rt_aij * xpq;
                        double cpx = xqc + rt_akl * xpq;
                        double xjxi = rjri0, xlxk = rlrk0;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[0];
                        s1 = c0x * s0;
                        G[1] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[2] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[3] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[0];
                        s1 = cpx * s0;
                        G[4] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        G[8] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[1];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[0];
                        G[5] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * G[4];
                        G[9] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[2];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[1];
                        G[6] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * G[5];
                        G[10] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[3];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[2];
                        G[7] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * G[6];
                        G[11] = s2;
                        s0 = s1;
                        s1 = s2;
                    }
                    {
                        double c0x = ypa - rt_aij * ypq;
                        double cpx = yqc + rt_akl * ypq;
                        double xjxi = rjri1, xlxk = rlrk1;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[12];
                        s1 = c0x * s0;
                        G[13] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[14] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[15] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[12];
                        s1 = cpx * s0;
                        G[16] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        G[20] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[13];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[12];
                        G[17] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * G[16];
                        G[21] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[14];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[13];
                        G[18] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * G[17];
                        G[22] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[15];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[14];
                        G[19] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * G[18];
                        G[23] = s2;
                        s0 = s1;
                        s1 = s2;
                    }
                    {
                        double c0x = zpa - rt_aij * zpq;
                        double cpx = zqc + rt_akl * zpq;
                        double xjxi = rjri2, xlxk = rlrk2;
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = G[24];
                        s1 = c0x * s0;
                        G[25] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        G[26] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        G[27] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[24];
                        s1 = cpx * s0;
                        G[28] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        G[32] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[25];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * G[24];
                        G[29] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * G[28];
                        G[33] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[26];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * G[25];
                        G[30] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * G[29];
                        G[34] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = G[27];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * G[26];
                        G[31] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * G[30];
                        G[35] = s2;
                        s0 = s1;
                        s1 = s2;
                    }
                    dd = dd_[0];
                    Ix = G[6];
                    Iy = G[12];
                    Iz = G[24];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[7];
                    fxi = ai2 * gix - 2 * G[5];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[10] - (1) * G[2];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[13];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[16];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[25];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[28];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[1];
                    Ix = G[5];
                    Iy = G[13];
                    Iz = G[24];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[6];
                    fxi = ai2 * gix - 1 * G[4];
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[9] - (1) * G[1];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[14];
                    fyi = ai2 * giy - 1 * G[12];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[17];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[25];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[28];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
