            int jj = j0 + jb_, kk = k0 + kb_, ll_ = l0 + lb_;
            double dfac;
            #pragma unroll
            for (int n = 0; n < 36; ++n) dd_[n] = 0.;
            if (do_k) {
                dfac = fac_sym * k_factor;
                dd_[0] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[1] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[2] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[3] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[4] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+0)]);
                dd_[7] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+1)]);
                dd_[8] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+2)]);
                dd_[9] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+3)]);
                dd_[10] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+4)]);
                dd_[11] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+5)]);
                dd_[12] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+0)]);
                dd_[13] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+1)]);
                dd_[14] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+2)]);
                dd_[15] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+3)]);
                dd_[16] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+4)]);
                dd_[17] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+5)]);
                dd_[18] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+0)]);
                dd_[19] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+1)]);
                dd_[20] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+2)]);
                dd_[21] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+3)]);
                dd_[22] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+4)]);
                dd_[23] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+5)]);
                dd_[24] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+0)]);
                dd_[25] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+1)]);
                dd_[26] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+2)]);
                dd_[27] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+3)]);
                dd_[28] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+4)]);
                dd_[29] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+5)]);
                dd_[30] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+0)]);
                dd_[31] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+4)]);
                dd_[35] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+5)]);
            }
            if (do_j) {
