                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[31];
                    Ix = gm5_0[1*NSQ];
                    Iy = gm5_1[1*NSQ];
                    Iz = gm5_2[0*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[2*NSQ];
                    fxi = ai2 * gix - 1 * gm5_0[0*NSQ];
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-3*NSQ];
                    fxk = ak2 * gm5_0[9*NSQ] - (kc[15]) * gm5_0[-7*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[2*NSQ];
                    fyi = ai2 * giy - 1 * gm5_1[0*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-3*NSQ];
                    fyk = ak2 * gm5_1[9*NSQ] - (kc[16]) * gm5_1[-7*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[1*NSQ];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-4*NSQ];
                    fzk = ak2 * gm5_2[8*NSQ] - (kc[17]) * gm5_2[-8*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[32];
                    Ix = gm5_0[1*NSQ];
                    Iy = gm5_1[0*NSQ];
                    Iz = gm5_2[1*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[2*NSQ];
                    fxi = ai2 * gix - 1 * gm5_0[0*NSQ];
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-3*NSQ];
                    fxk = ak2 * gm5_0[9*NSQ] - (kc[15]) * gm5_0[-7*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[1*NSQ];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-4*NSQ];
                    fyk = ak2 * gm5_1[8*NSQ] - (kc[16]) * gm5_1[-8*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[2*NSQ];
                    fzi = ai2 * giz - 1 * gm5_2[0*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-3*NSQ];
                    fzk = ak2 * gm5_2[9*NSQ] - (kc[17]) * gm5_2[-7*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[33];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[2*NSQ];
                    Iz = gm5_2[0*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-4*NSQ];
                    fxk = ak2 * gm5_0[8*NSQ] - (kc[15]) * gm5_0[-8*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[3*NSQ];
                    fyi = ai2 * giy - 2 * gm5_1[1*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-2*NSQ];
                    fyk = ak2 * gm5_1[10*NSQ] - (kc[16]) * gm5_1[-6*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[1*NSQ];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-4*NSQ];
                    fzk = ak2 * gm5_2[8*NSQ] - (kc[17]) * gm5_2[-8*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[34];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[1*NSQ];
                    Iz = gm5_2[1*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-4*NSQ];
                    fxk = ak2 * gm5_0[8*NSQ] - (kc[15]) * gm5_0[-8*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[2*NSQ];
                    fyi = ai2 * giy - 1 * gm5_1[0*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-3*NSQ];
                    fyk = ak2 * gm5_1[9*NSQ] - (kc[16]) * gm5_1[-7*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[2*NSQ];
                    fzi = ai2 * giz - 1 * gm5_2[0*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-3*NSQ];
                    fzk = ak2 * gm5_2[9*NSQ] - (kc[17]) * gm5_2[-7*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[35];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[0*NSQ];
                    Iz = gm5_2[2*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-4*NSQ];
                    fxk = ak2 * gm5_0[8*NSQ] - (kc[15]) * gm5_0[-8*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[1*NSQ];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-4*NSQ];
                    fyk = ak2 * gm5_1[8*NSQ] - (kc[16]) * gm5_1[-8*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[3*NSQ];
                    fzi = ai2 * giz - 2 * gm5_2[1*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-2*NSQ];
                    fzk = ak2 * gm5_2[10*NSQ] - (kc[17]) * gm5_2[-6*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        __syncthreads();
        reduce[0*threads] = v_kx;  reduce[1*threads] = v_ky;
        reduce[2*threads] = v_kz;  reduce[3*threads] = v_lx;
        reduce[4*threads] = v_ly;  reduce[5*threads] = v_lz;
        // GSTRIDE need not be a power of two (nfj*nfk*nfl/PER is not), so
        // the tree starts at the next power of two and guards the odd half
        for (int i = 16; i > 0; i >>= 1) {
            __syncthreads();
            if (gout_id < i && gout_id + i < GSTRIDE) {
#pragma unroll
                for (int n = 0; n < 6; ++n) {
                    reduce[n*threads] += reduce[n*threads+i*NSQ];
                }
            }
        }
        if (gout_id == 0 && task_id < ntasks) {
            int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
            int la = bas[lsh*BAS_SLOTS+ATOM_OF];
            atomicAdd(ejk+ka*3+0, reduce[0*threads]);
            atomicAdd(ejk+ka*3+1, reduce[1*threads]);
            atomicAdd(ejk+ka*3+2, reduce[2*threads]);
            atomicAdd(ejk+la*3+0, reduce[3*threads]);
            atomicAdd(ejk+la*3+1, reduce[4*threads]);
            atomicAdd(ejk+la*3+2, reduce[5*threads]);
        }
    }
    __syncthreads();
    reduce[0*threads] = v_ix;  reduce[1*threads] = v_iy;
    reduce[2*threads] = v_iz;  reduce[3*threads] = v_jx;
    reduce[4*threads] = v_jy;  reduce[5*threads] = v_jz;
    for (int i = 128; i > 0; i >>= 1) {
        __syncthreads();
        if (thread_id < i && thread_id + i < threads) {
#pragma unroll
            for (int n = 0; n < 6; ++n) {
                reduce[n*threads] += reduce[n*threads+i];
            }
        }
    }
    if (thread_id == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, reduce[0*threads]);
        atomicAdd(ejk+ia*3+1, reduce[1*threads]);
        atomicAdd(ejk+ia*3+2, reduce[2*threads]);
        atomicAdd(ejk+ja*3+0, reduce[3*threads]);
        atomicAdd(ejk+ja*3+1, reduce[4*threads]);
        atomicAdd(ejk+ja*3+2, reduce[5*threads]);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (2200) reg : 36 gout, g_size 24, 3 roots, one thread per quartet
extern "C" __global__ void __launch_bounds__(256, 1)
ejk_2200(EARGS)
{
    constexpr int NROOTS = 3;
    constexpr int GSZ = 24;
    constexpr int threads = 256;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36], s_ai2[36], s_aj2[36];
    __shared__ int ntasks, pair_ij, ish, jsh;
    __shared__ double ri[3], rjri[3];
    int thread_id = threadIdx.x;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    int do_j = j_factor != 0.;
    int do_k = k_factor != 0.;
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = thread_id; task_id < ntasks; task_id += threads) {
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (ish == jsh) fac_sym *= .5;
        if (ksh == lsh) fac_sym *= .5;
        if (bas_ij == bas_kl) fac_sym *= .5;
        const double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
        const double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
        const double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
        const double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        double rlrk0 = rl[0]-rk[0], rlrk1 = rl[1]-rk[1], rlrk2 = rl[2]-rk[2];
        double rr_kl = rlrk0*rlrk0 + rlrk1*rlrk1 + rlrk2*rlrk2;
        double dd_[36];
        int i0 = ao_loc[ish], j0 = ao_loc[jsh];
        int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
        double dfac;
        #pragma unroll
        for (int n = 0; n < 36; ++n) dd_[n] = 0.;
        if (do_k) {
            dfac = fac_sym * k_factor;
            dd_[0] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[1] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[2] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[3] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[4] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[5] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
            dd_[6] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[7] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[8] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[9] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[10] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[11] += dfac * (dm[(j0+1)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+1)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
            dd_[12] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[13] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[14] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[15] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[16] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[17] += dfac * (dm[(j0+2)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+2)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
            dd_[18] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[19] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[20] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[21] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
            dd_[22] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+4)]);
            dd_[23] += dfac * (dm[(j0+3)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+5)] + dm[(j0+3)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+5)]);
            dd_[24] += dfac * (dm[(j0+4)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+4)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+0)]);
            dd_[25] += dfac * (dm[(j0+4)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+4)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+1)]);
            dd_[26] += dfac * (dm[(j0+4)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+4)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+2)]);
            dd_[27] += dfac * (dm[(j0+4)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+4)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+3)]);
