      jc[16] = c_lex[12+pj+1];
      kc[16] = c_lex[12+pk+1];
      gb[16] = (jc[16]*4 + kc[16]*12 + c_lex[0+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[17] = c_lex[12+pj+2];
      kc[17] = c_lex[12+pk+2];
      gb[17] = (jc[17]*4 + kc[17]*12 + c_lex[0+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (bas_ij == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
        }
        double dd_[36];
        {
            int i0 = ao_loc[ish], j0 = ao_loc[jsh];
            int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
            int jj = j0 + jb_, kk = k0 + kb_, ll_ = l0 + lb_;
            double dfac;
            #pragma unroll
            for (int n = 0; n < 36; ++n) dd_[n] = 0.;
            if (do_k) {
                dfac = fac_sym * k_factor;
                dd_[0] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[1] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[2] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[3] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[4] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+0)]);
                dd_[7] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+1)]);
                dd_[8] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+2)]);
                dd_[9] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+3)]);
                dd_[10] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+4)]);
                dd_[11] += dfac * (dm[(jj+0)*nao+(kk+1)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+1)*nao+(i0+5)]);
                dd_[12] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+0)]);
                dd_[13] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+1)]);
                dd_[14] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+2)]);
                dd_[15] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+3)]);
                dd_[16] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+4)]);
                dd_[17] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+5)]);
                dd_[18] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+0)]);
                dd_[19] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+1)]);
                dd_[20] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+2)]);
                dd_[21] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+3)]);
                dd_[22] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+4)]);
                dd_[23] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+5)]);
                dd_[24] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+0)]);
                dd_[25] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+1)]);
                dd_[26] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+2)]);
                dd_[27] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+3)]);
                dd_[28] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+4)]);
                dd_[29] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+5)]);
                dd_[30] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+0)]);
                dd_[31] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+4)]);
                dd_[35] += dfac * (dm[(jj+0)*nao+(kk+5)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+5)*nao+(i0+5)]);
            }
            if (do_j) {
                dfac = fac_sym * j_factor;
                dd_[0] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[1] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[2] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[3] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[4] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[7] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[8] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[9] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[10] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[11] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[12] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[13] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[14] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[15] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[16] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[17] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[18] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[19] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[20] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[21] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[22] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[23] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[24] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[25] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[26] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[27] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[28] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[29] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[30] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[31] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[35] += dfac * (dm[(ll_+0)*nao+(kk+5)] * dm[(jj+0)*nao+(i0+5)]);
            }
        }
        double v_kx = 0, v_ky = 0, v_kz = 0, v_lx = 0, v_ly = 0, v_lz = 0;
        double dd, Ix, Iy, Iz, pxy, pxz, pyz;
        double gix, giy, giz;
        double fxi, fyi, fzi, fxj, fyj, fzj, fxk, fyk, fzk;
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            if (gout_id == 0) {
                const double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
                const double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
                const double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
                const double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
                double ak = expk[klp/lprim];
                double al = expl[klp%lprim];
                double akl = ak + al;
                double iakl = 1. / akl;
                double al_akl = al * iakl;
                double xlxk = rlrk[0*NSQ], ylyk = rlrk[1*NSQ], zlzk = rlrk[2*NSQ];
                double Kcd = exp(-ak * al_akl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                gx[0] = ck[klp/lprim] * cl[klp%lprim] * Kcd;
                akl_cache[0*NSQ] = akl;
                akl_cache[1*NSQ] = al_akl;
                akl_cache[2*NSQ] = iakl;
                akl_cache[3*NSQ] = ak + ak;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                __syncthreads();
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double ai2 = s_ai2[ijp], aj2 = s_aj2[ijp];
                double akl = akl_cache[0*NSQ];
                double al_akl = akl_cache[1*NSQ];
                double iakl = akl_cache[2*NSQ];
                double ak2 = akl_cache[3*NSQ];
                // inv_om2 = 0 is the full-range operator, 1/omega^2 the
                // long-range (erf) one -- one fma, see fastejk_prologue.cu
                double inv_s = rsqrt(fma(aij * akl, inv_om2, aij + akl));
                double inv_s2 = inv_s * inv_s;
                double xkl = rk[0] + rlrk[0*NSQ] * al_akl;
                double ykl = rk[1] + rlrk[1*NSQ] * al_akl;
                double zkl = rk[2] + rlrk[2*NSQ] * al_akl;
                double xpq = s_xij[ijp] - xkl;
                double ypq = s_yij[ijp] - ykl;
                double zpq = s_zij[ijp] - zkl;
                if (gout_id == 0) {
                    Rpq[0*NSQ] = xpq;
                    Rpq[1*NSQ] = ypq;
                    Rpq[2*NSQ] = zpq;
                    gx[NSQ*g_size] = s_cicj[ijp] * iaij * iakl * inv_s * coef0;
                }
                double rr = xpq*xpq + ypq*ypq + zpq*zpq;
                ejk_roots_tab<NROOTS>(aij*akl*inv_s2 * rr, rw, NSQ, gout_id,
                                      GSTRIDE, tab);
                for (int irys = 0; irys < NROOTS; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[2*irys*NSQ];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    (void)b10; (void)b00; (void)b01; (void)s2;
                    for (int n = gout_id; n < 3; n += GSTRIDE) {
                        if (n == 2) { gx[2*g_size*NSQ] = rw[(2*irys+1)*NSQ]; }
                        double *_gx = gx + n * g_size * NSQ;
                        double xjxi = rjri[n], xlxk = rlrk[n*NSQ];
                        double c0x = xjxi * s_ajaij[ijp] - rt_aij * Rpq[n*NSQ];
                        double cpx = xlxk * al_akl + rt_akl * Rpq[n*NSQ];
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = _gx[0*NSQ];
                        s1 = c0x * s0;
                        _gx[1*NSQ] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[5*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[12*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        _gx[24*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        _gx[36*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[13*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * _gx[12*NSQ];
                        _gx[25*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 1 * b00 * _gx[24*NSQ];
                        _gx[37*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[2*NSQ];
                        s1 = cpx * s0;
                        s1 += 2 * b00 * _gx[1*NSQ];
                        _gx[14*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 2 * b00 * _gx[13*NSQ];
                        _gx[26*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        s2 += 2 * b00 * _gx[25*NSQ];
                        _gx[38*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[3*NSQ];
                        s1 = cpx * s0;
                        s1 += 3 * b00 * _gx[2*NSQ];
                        _gx[15*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 3 * b00 * _gx[14*NSQ];
                        _gx[27*NSQ] = s2;
                        s0 = s1;
