{
    constexpr int NSQ = 4;
    constexpr int GSTRIDE = 36;
    constexpr int NROOTS = 5;
    constexpr int g_size = 144;
    constexpr int PAD = 12;
    constexpr int HEADSZ = (10 + PAD) * NSQ;
    constexpr int threads = NSQ * GSTRIDE;
