    // which are both rebuilt by the next task; it must stay clear of the pad
    double *reduce = shared_memory + HEADSZ + thread_id;
    // the j and k lowering terms read g(j-1) and g(k-1) at a lane-uniform
    // power that may be zero; the multiplier is then zero but the address is
    // still evaluated, so it lands in this zeroed pad instead of out of bounds
    for (int t = thread_id; t < PAD*NSQ; t += threads) {
        shared_memory[10*NSQ + t] = 0.;
    }
    int o_base = gout_id * 6;
    int lb_ = o_base % 6;
    int kb_ = (o_base / 6) % 6;
    int jb_ = o_base / 36;
    int gb[18], jc[18], kc[18];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      jc[0] = c_lex[12+pj+0];
      kc[0] = c_lex[12+pk+0];
      gb[0] = (jc[0]*4 + kc[0]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[1] = c_lex[12+pj+1];
      kc[1] = c_lex[12+pk+1];
      gb[1] = (jc[1]*4 + kc[1]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[2] = c_lex[12+pj+2];
      kc[2] = c_lex[12+pk+2];
      gb[2] = (jc[2]*4 + kc[2]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+1)*3;
      jc[3] = c_lex[12+pj+0];
      kc[3] = c_lex[12+pk+0];
      gb[3] = (jc[3]*4 + kc[3]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[12+pj+1];
      kc[4] = c_lex[12+pk+1];
      gb[4] = (jc[4]*4 + kc[4]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[12+pj+2];
      kc[5] = c_lex[12+pk+2];
      gb[5] = (jc[5]*4 + kc[5]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+2)*3;
      jc[6] = c_lex[12+pj+0];
      kc[6] = c_lex[12+pk+0];
      gb[6] = (jc[6]*4 + kc[6]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[12+pj+1];
      kc[7] = c_lex[12+pk+1];
      gb[7] = (jc[7]*4 + kc[7]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[8] = c_lex[12+pj+2];
      kc[8] = c_lex[12+pk+2];
      gb[8] = (jc[8]*4 + kc[8]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+3)*3;
      jc[9] = c_lex[12+pj+0];
      kc[9] = c_lex[12+pk+0];
      gb[9] = (jc[9]*4 + kc[9]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[10] = c_lex[12+pj+1];
      kc[10] = c_lex[12+pk+1];
      gb[10] = (jc[10]*4 + kc[10]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[11] = c_lex[12+pj+2];
      kc[11] = c_lex[12+pk+2];
      gb[11] = (jc[11]*4 + kc[11]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+4)*3;
      jc[12] = c_lex[12+pj+0];
      kc[12] = c_lex[12+pk+0];
      gb[12] = (jc[12]*4 + kc[12]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[13] = c_lex[12+pj+1];
      kc[13] = c_lex[12+pk+1];
      gb[13] = (jc[13]*4 + kc[13]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[14] = c_lex[12+pj+2];
      kc[14] = c_lex[12+pk+2];
      gb[14] = (jc[14]*4 + kc[14]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+5)*3;
      jc[15] = c_lex[12+pj+0];
      kc[15] = c_lex[12+pk+0];
      gb[15] = (jc[15]*4 + kc[15]*12 + c_lex[12+pl+0]*48)*NSQ + 0*g_size*NSQ;
      jc[16] = c_lex[12+pj+1];
      kc[16] = c_lex[12+pk+1];
      gb[16] = (jc[16]*4 + kc[16]*12 + c_lex[12+pl+1]*48)*NSQ + 1*g_size*NSQ;
      jc[17] = c_lex[12+pj+2];
      kc[17] = c_lex[12+pk+2];
      gb[17] = (jc[17]*4 + kc[17]*12 + c_lex[12+pl+2]*48)*NSQ + 2*g_size*NSQ;
    }
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (bas_ij == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
        }
        double dd_[36];
        {
            int i0 = ao_loc[ish], j0 = ao_loc[jsh];
            int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
            int jj = j0 + jb_, kk = k0 + kb_, ll_ = l0 + lb_;
            double dfac;
            #pragma unroll
            for (int n = 0; n < 36; ++n) dd_[n] = 0.;
            if (do_k) {
                dfac = fac_sym * k_factor;
                dd_[0] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[1] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[2] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[3] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[4] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[7] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[8] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[9] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[10] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[11] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[12] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[13] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[14] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[15] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[16] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+4)]);
