                dd_[4] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[7] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[8] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[9] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[10] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[11] += dfac * (dm[(ll_+1)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[12] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[13] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[14] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[15] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[16] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[17] += dfac * (dm[(ll_+2)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[18] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[19] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[20] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[21] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[22] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[23] += dfac * (dm[(ll_+3)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[24] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[25] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[26] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[27] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[28] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[29] += dfac * (dm[(ll_+4)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[30] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[31] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[35] += dfac * (dm[(ll_+5)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+5)]);
            }
        }
        double v_kx = 0, v_ky = 0, v_kz = 0, v_lx = 0, v_ly = 0, v_lz = 0;
        double dd, Ix, Iy, Iz, pxy, pxz, pyz;
        double gix, giy, giz;
        double fxi, fyi, fzi, fxj, fyj, fzj, fxk, fyk, fzk;
        for (int klp = 0; klp < kprim*lprim; ++klp) {
            __syncthreads();
            if (gout_id == 0) {
                const double *expk = env + bas[ksh*BAS_SLOTS+PTR_EXP];
                const double *expl = env + bas[lsh*BAS_SLOTS+PTR_EXP];
                const double *ck = env + bas[ksh*BAS_SLOTS+PTR_COEFF];
                const double *cl = env + bas[lsh*BAS_SLOTS+PTR_COEFF];
                double ak = expk[klp/lprim];
                double al = expl[klp%lprim];
                double akl = ak + al;
                double iakl = 1. / akl;
                double al_akl = al * iakl;
                double xlxk = rlrk[0*NSQ], ylyk = rlrk[1*NSQ], zlzk = rlrk[2*NSQ];
                double Kcd = exp(-ak * al_akl * (xlxk*xlxk+ylyk*ylyk+zlzk*zlzk));
                gx[0] = ck[klp/lprim] * cl[klp%lprim] * Kcd;
                akl_cache[0*NSQ] = akl;
                akl_cache[1*NSQ] = al_akl;
                akl_cache[2*NSQ] = iakl;
                akl_cache[3*NSQ] = ak + ak;
            }
            for (int ijp = 0; ijp < iprim*jprim; ++ijp) {
                __syncthreads();
                double aij = s_aij[ijp];
                double iaij = s_iaij[ijp];
                double ai2 = s_ai2[ijp], aj2 = s_aj2[ijp];
                double akl = akl_cache[0*NSQ];
                double al_akl = akl_cache[1*NSQ];
                double iakl = akl_cache[2*NSQ];
                double ak2 = akl_cache[3*NSQ];
                // inv_om2 = 0 is the full-range operator, 1/omega^2 the
                // long-range (erf) one -- one fma, see fastejk_prologue.cu
