            dd_[7] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+7)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+7)]);
            dd_[8] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+8)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+8)]);
            dd_[9] += dfac * (dm[(j0+0)*nao+(k0+0)] * dm[(l0+0)*nao+(i0+9)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+0)*nao+(i0+9)]);
            dd_[10] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+0)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+0)]);
            dd_[11] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+1)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+1)]);
            dd_[12] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+2)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+2)]);
            dd_[13] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+3)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+3)]);
            dd_[14] += dfac * (dm[(j0+0)*nao+(k0+1)] * dm[(l0+0)*nao+(i0+4)] + dm[(j0+0)*nao+(l0+0)] * dm[(k0+1)*nao+(i0+4)]);
