                    fzi = ai2 * giz - 1 * G[35];
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[41] - (1) * G[31];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[28];
                    Ix = G[0];
                    Iy = G[16];
