                    Iy = G[21];
                    Iz = G[52];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[5];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[22];
                    fyi = ai2 * giy - 1 * G[20];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[26];
