                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[53];
                    fzi = ai2 * giz - 2 * G[51];
                    fzj = aj2 * (giz - rjri2 * Iz);
                    fzk = ak2 * G[57] - (2) * G[47];
