                    Ix = G[0];
                    Iy = G[20];
                    Iz = G[53];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[5];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[21];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[25];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
