                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[24];
                    fyi = ai2 * giy - 3 * G[22];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[33];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[46];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[40];
                    fzk = ak2 * G[55];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[27];
                    Ix = G[0];
                    Iy = G[22];
                    Iz = G[46];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[10];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[23];
                    fyi = ai2 * giy - 2 * G[21];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[32];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[47];
                    fzi = ai2 * giz - 1 * G[45];
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[41];
                    fzk = ak2 * G[56];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[28];
                    Ix = G[0];
                    Iy = G[21];
                    Iz = G[47];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[10];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[22];
                    fyi = ai2 * giy - 1 * G[20];
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[31];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[48];
                    fzi = ai2 * giz - 2 * G[46];
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[42];
                    fzk = ak2 * G[57];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[29];
                    Ix = G[0];
                    Iy = G[20];
                    Iz = G[48];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = G[1];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix);
                    fxk = ak2 * G[10];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = G[21];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy);
                    fyk = ak2 * G[30];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = G[49];
                    fzi = ai2 * giz - 3 * G[47];
                    fzj = aj2 * (giz - rjri2 * Iz) - (1) * G[43];
                    fzk = ak2 * G[58];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
        int la = bas[lsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ka*3+0, v_kx);
        atomicAdd(ejk+ka*3+1, v_ky);
        atomicAdd(ejk+ka*3+2, v_kz);
        atomicAdd(ejk+la*3+0, v_lx);
        atomicAdd(ejk+la*3+1, v_ly);
        atomicAdd(ejk+la*3+2, v_lz);
    }
    // every thread of the block shares ish/jsh, so the bra half reduces inside
    // the warp before it reaches the six atomics
#pragma unroll
    for (int off = 16; off > 0; off >>= 1) {
        v_ix += __shfl_down_sync(0xffffffff, v_ix, off);
        v_iy += __shfl_down_sync(0xffffffff, v_iy, off);
        v_iz += __shfl_down_sync(0xffffffff, v_iz, off);
        v_jx += __shfl_down_sync(0xffffffff, v_jx, off);
        v_jy += __shfl_down_sync(0xffffffff, v_jy, off);
        v_jz += __shfl_down_sync(0xffffffff, v_jz, off);
    }
    if ((thread_id & 31) == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, v_ix);
        atomicAdd(ejk+ia*3+1, v_iy);
        atomicAdd(ejk+ia*3+2, v_iz);
        atomicAdd(ejk+ja*3+0, v_jx);
        atomicAdd(ejk+ja*3+1, v_jy);
        atomicAdd(ejk+ja*3+2, v_jz);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (3110) shm : 90 gout over 3 lanes, 32 quartets/block, 30 dd/lane
extern "C" __global__ void __launch_bounds__(96, 1)
ejk_3110(EARGS)
{
    constexpr int NSQ = 32;
    constexpr int GSTRIDE = 3;
    constexpr int NROOTS = 4;
    constexpr int g_size = 30;
    constexpr int PAD = 10;
    constexpr int HEADSZ = (10 + PAD) * NSQ;
    constexpr int threads = NSQ * GSTRIDE;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36], s_ai2[36], s_aj2[36];
    __shared__ int ntasks, pair_ij, ish, jsh;
    __shared__ double ri[3], rjri[3];
    extern __shared__ double shared_memory[];
    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = NSQ * gout_id + sq_id;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    int do_j = j_factor != 0.;
    int do_k = k_factor != 0.;
    double *rlrk = shared_memory + sq_id;
    double *Rpq  = shared_memory + NSQ*3 + sq_id;
    double *akl_cache = shared_memory + NSQ*6 + sq_id;
    double *gx = shared_memory + (10 + PAD)*NSQ + sq_id;
    double *rw = shared_memory + (10 + PAD + 3*g_size)*NSQ + sq_id;
    // the reduction buffer sits on top of the 2D integrals and the roots,
    // which are both rebuilt by the next task; it must stay clear of the pad
    double *reduce = shared_memory + HEADSZ + thread_id;
    // the j and k lowering terms read g(j-1) and g(k-1) at a lane-uniform
    // power that may be zero; the multiplier is then zero but the address is
    // still evaluated, so it lands in this zeroed pad instead of out of bounds
    for (int t = thread_id; t < PAD*NSQ; t += threads) {
        shared_memory[10*NSQ + t] = 0.;
    }
    int o_base = gout_id * 3;
    int lb_ = o_base % 1;
    int kb_ = (o_base / 1) % 3;
    int jb_ = o_base / 3;
    int gb[9], jc[9], kc[9];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      jc[0] = c_lex[3+pj+0];
      kc[0] = c_lex[3+pk+0];
      gb[0] = (jc[0]*5 + kc[0]*10 + c_lex[0+pl+0]*30)*NSQ + 0*g_size*NSQ;
      jc[1] = c_lex[3+pj+1];
      kc[1] = c_lex[3+pk+1];
      gb[1] = (jc[1]*5 + kc[1]*10 + c_lex[0+pl+1]*30)*NSQ + 1*g_size*NSQ;
      jc[2] = c_lex[3+pj+2];
      kc[2] = c_lex[3+pk+2];
      gb[2] = (jc[2]*5 + kc[2]*10 + c_lex[0+pl+2]*30)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+1)*3, pl = (lb_+0)*3;
      jc[3] = c_lex[3+pj+0];
      kc[3] = c_lex[3+pk+0];
      gb[3] = (jc[3]*5 + kc[3]*10 + c_lex[0+pl+0]*30)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[3+pj+1];
      kc[4] = c_lex[3+pk+1];
      gb[4] = (jc[4]*5 + kc[4]*10 + c_lex[0+pl+1]*30)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[3+pj+2];
      kc[5] = c_lex[3+pk+2];
      gb[5] = (jc[5]*5 + kc[5]*10 + c_lex[0+pl+2]*30)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+2)*3, pl = (lb_+0)*3;
      jc[6] = c_lex[3+pj+0];
      kc[6] = c_lex[3+pk+0];
      gb[6] = (jc[6]*5 + kc[6]*10 + c_lex[0+pl+0]*30)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[3+pj+1];
      kc[7] = c_lex[3+pk+1];
      gb[7] = (jc[7]*5 + kc[7]*10 + c_lex[0+pl+1]*30)*NSQ + 1*g_size*NSQ;
      jc[8] = c_lex[3+pj+2];
      kc[8] = c_lex[3+pk+2];
      gb[8] = (jc[8]*5 + kc[8]*10 + c_lex[0+pl+2]*30)*NSQ + 2*g_size*NSQ;
    }
