                dd_[8] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+8)]);
                dd_[9] += dfac * (dm[(ll_+0)*nao+(kk+0)] * dm[(jj+0)*nao+(i0+9)]);
                dd_[10] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+0)]);
                dd_[11] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[12] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[13] += dfac * (dm[(ll_+0)*nao+(kk+1)] * dm[(jj+0)*nao+(i0+3)]);
