                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-4*NSQ];
                    fyk = ak2 * gm5_1[11*NSQ] - (kc[16]) * gm5_1[-9*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[2*NSQ];
                    fzi = ai2 * giz - 1 * gm5_2[0*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-4*NSQ];
                    fzk = ak2 * gm5_2[11*NSQ] - (kc[17]) * gm5_2[-9*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[55];
                    Ix = gm5_0[1*NSQ];
                    Iy = gm5_1[0*NSQ];
                    Iz = gm5_2[2*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
