                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-5*NSQ];
                    fxk = ak2 * gm5_0[10*NSQ] - (kc[15]) * gm5_0[-10*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[4*NSQ];
                    fyi = ai2 * giy - 3 * gm5_1[2*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-2*NSQ];
                    fyk = ak2 * gm5_1[13*NSQ] - (kc[16]) * gm5_1[-7*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[1*NSQ];
                    fzi = ai2 * giz;
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-5*NSQ];
                    fzk = ak2 * gm5_2[10*NSQ] - (kc[17]) * gm5_2[-10*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[57];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[2*NSQ];
                    Iz = gm5_2[1*NSQ];
