                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-4*NSQ];
                    fzk = ak2 * gm5_2[11*NSQ] - (kc[17]) * gm5_2[-9*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[58];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[1*NSQ];
                    Iz = gm5_2[2*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-5*NSQ];
                    fxk = ak2 * gm5_0[10*NSQ] - (kc[15]) * gm5_0[-10*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[2*NSQ];
                    fyi = ai2 * giy - 1 * gm5_1[0*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-4*NSQ];
                    fyk = ak2 * gm5_1[11*NSQ] - (kc[16]) * gm5_1[-9*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[3*NSQ];
                    fzi = ai2 * giz - 2 * gm5_2[1*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-3*NSQ];
                    fzk = ak2 * gm5_2[12*NSQ] - (kc[17]) * gm5_2[-8*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[59];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[0*NSQ];
                    Iz = gm5_2[3*NSQ];
                    pxy = Ix * Iy * dd;
                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm5_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-5*NSQ];
                    fxk = ak2 * gm5_0[10*NSQ] - (kc[15]) * gm5_0[-10*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[1*NSQ];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-5*NSQ];
                    fyk = ak2 * gm5_1[10*NSQ] - (kc[16]) * gm5_1[-10*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[4*NSQ];
                    fzi = ai2 * giz - 3 * gm5_2[2*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-2*NSQ];
                    fzk = ak2 * gm5_2[13*NSQ] - (kc[17]) * gm5_2[-7*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        __syncthreads();
        reduce[0*threads] = v_kx;  reduce[1*threads] = v_ky;
        reduce[2*threads] = v_kz;  reduce[3*threads] = v_lx;
        reduce[4*threads] = v_ly;  reduce[5*threads] = v_lz;
        // GSTRIDE need not be a power of two (nfj*nfk*nfl/PER is not), so
        // the tree starts at the next power of two and guards the odd half
        for (int i = 16; i > 0; i >>= 1) {
            __syncthreads();
            if (gout_id < i && gout_id + i < GSTRIDE) {
#pragma unroll
                for (int n = 0; n < 6; ++n) {
                    reduce[n*threads] += reduce[n*threads+i*NSQ];
                }
            }
        }
        if (gout_id == 0 && task_id < ntasks) {
            int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
            int la = bas[lsh*BAS_SLOTS+ATOM_OF];
            atomicAdd(ejk+ka*3+0, reduce[0*threads]);
            atomicAdd(ejk+ka*3+1, reduce[1*threads]);
            atomicAdd(ejk+ka*3+2, reduce[2*threads]);
            atomicAdd(ejk+la*3+0, reduce[3*threads]);
            atomicAdd(ejk+la*3+1, reduce[4*threads]);
            atomicAdd(ejk+la*3+2, reduce[5*threads]);
        }
    }
    __syncthreads();
    reduce[0*threads] = v_ix;  reduce[1*threads] = v_iy;
    reduce[2*threads] = v_iz;  reduce[3*threads] = v_jx;
    reduce[4*threads] = v_jy;  reduce[5*threads] = v_jz;
    for (int i = 128; i > 0; i >>= 1) {
        __syncthreads();
        if (thread_id < i && thread_id + i < threads) {
#pragma unroll
            for (int n = 0; n < 6; ++n) {
                reduce[n*threads] += reduce[n*threads+i];
            }
        }
    }
    if (thread_id == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, reduce[0*threads]);
        atomicAdd(ejk+ia*3+1, reduce[1*threads]);
        atomicAdd(ejk+ia*3+2, reduce[2*threads]);
        atomicAdd(ejk+ja*3+0, reduce[3*threads]);
        atomicAdd(ejk+ja*3+1, reduce[4*threads]);
        atomicAdd(ejk+ja*3+2, reduce[5*threads]);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (3133) shm : 3000 gout over 60 lanes, 4 quartets/block, 50 dd/lane
extern "C" __global__ void __launch_bounds__(240, 1)
ejk_3133(EARGS)
{
