    int lb_ = o_base % 3;
    int kb_ = (o_base / 3) % 3;
    int jb_ = o_base / 9;
    int gb[9], jc[9], kc[9];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      jc[0] = c_lex[12+pj+0];
      kc[0] = c_lex[3+pk+0];
      gb[0] = (jc[0]*5 + kc[0]*15 + c_lex[3+pl+0]*45)*NSQ + 0*g_size*NSQ;
      jc[1] = c_lex[12+pj+1];
      kc[1] = c_lex[3+pk+1];
      gb[1] = (jc[1]*5 + kc[1]*15 + c_lex[3+pl+1]*45)*NSQ + 1*g_size*NSQ;
      jc[2] = c_lex[12+pj+2];
      kc[2] = c_lex[3+pk+2];
      gb[2] = (jc[2]*5 + kc[2]*15 + c_lex[3+pl+2]*45)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+1)*3;
