      kc[3] = c_lex[3+pk+0];
      gb[3] = (jc[3]*5 + kc[3]*15 + c_lex[3+pl+0]*45)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[12+pj+1];
      kc[4] = c_lex[3+pk+1];
      gb[4] = (jc[4]*5 + kc[4]*15 + c_lex[3+pl+1]*45)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[12+pj+2];
      kc[5] = c_lex[3+pk+2];
      gb[5] = (jc[5]*5 + kc[5]*15 + c_lex[3+pl+2]*45)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+2)*3;
