      kc[6] = c_lex[3+pk+0];
      gb[6] = (jc[6]*5 + kc[6]*15 + c_lex[3+pl+0]*45)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[12+pj+1];
      kc[7] = c_lex[3+pk+1];
      gb[7] = (jc[7]*5 + kc[7]*15 + c_lex[3+pl+1]*45)*NSQ + 1*g_size*NSQ;
      jc[8] = c_lex[12+pj+2];
      kc[8] = c_lex[3+pk+2];
