                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[8]) * gm2_2[-2*NSQ];
                    fzk = ak2 * gm2_2[18*NSQ] - (kc[8]) * gm2_2[-12*NSQ];
                    v_iz += fzi * pxy;
