                    fzk = ak2 * gm5_2[16*NSQ] - (kc[17]) * gm5_2[-14*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[58];
                    Ix = gm5_0[0*NSQ];
                    Iy = gm5_1[1*NSQ];
                    Iz = gm5_2[2*NSQ];
