                dd_[20] += dfac * (dm[(jj+0)*nao+(kk+2)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+2)*nao+(i0+0)]);
