                dd_[32] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(jj+0)*nao+(kk+3)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+3)*nao+(i0+4)]);
