                dd_[48] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+8)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+8)]);
                dd_[49] += dfac * (dm[(jj+0)*nao+(kk+4)] * dm[(ll_+0)*nao+(i0+9)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+4)*nao+(i0+9)]);
