                dd_[23] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+3)]);
                dd_[24] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[25] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[26] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+6)]);
                dd_[27] += dfac * (dm[(ll_+0)*nao+(kk+2)] * dm[(jj+0)*nao+(i0+7)]);
