                dd_[31] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+3)]);
