                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[15]) * gm5_0[-5*NSQ];
                    fxk = ak2 * gm5_0[15*NSQ] - (kc[15]) * gm5_0[-15*NSQ];
                    v_ix += fxi * pyz;
                    v_jx += fxj * pyz;
                    v_kx += fxk * pyz;
                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm5_1[1*NSQ];
                    fyi = ai2 * giy;
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[16]) * gm5_1[-5*NSQ];
                    fyk = ak2 * gm5_1[15*NSQ] - (kc[16]) * gm5_1[-15*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm5_2[4*NSQ];
                    fzi = ai2 * giz - 3 * gm5_2[2*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[17]) * gm5_2[-2*NSQ];
                    fzk = ak2 * gm5_2[18*NSQ] - (kc[17]) * gm5_2[-12*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                }
            }
        }
        __syncthreads();
        reduce[0*threads] = v_kx;  reduce[1*threads] = v_ky;
        reduce[2*threads] = v_kz;  reduce[3*threads] = v_lx;
        reduce[4*threads] = v_ly;  reduce[5*threads] = v_lz;
        // GSTRIDE need not be a power of two (nfj*nfk*nfl/PER is not), so
        // the tree starts at the next power of two and guards the odd half
        for (int i = 16; i > 0; i >>= 1) {
            __syncthreads();
            if (gout_id < i && gout_id + i < GSTRIDE) {
#pragma unroll
                for (int n = 0; n < 6; ++n) {
                    reduce[n*threads] += reduce[n*threads+i*NSQ];
                }
            }
        }
        if (gout_id == 0 && task_id < ntasks) {
            int ka = bas[ksh*BAS_SLOTS+ATOM_OF];
            int la = bas[lsh*BAS_SLOTS+ATOM_OF];
            atomicAdd(ejk+ka*3+0, reduce[0*threads]);
            atomicAdd(ejk+ka*3+1, reduce[1*threads]);
            atomicAdd(ejk+ka*3+2, reduce[2*threads]);
            atomicAdd(ejk+la*3+0, reduce[3*threads]);
            atomicAdd(ejk+la*3+1, reduce[4*threads]);
            atomicAdd(ejk+la*3+2, reduce[5*threads]);
        }
    }
    __syncthreads();
    reduce[0*threads] = v_ix;  reduce[1*threads] = v_iy;
    reduce[2*threads] = v_iz;  reduce[3*threads] = v_jx;
    reduce[4*threads] = v_jy;  reduce[5*threads] = v_jz;
    for (int i = 128; i > 0; i >>= 1) {
        __syncthreads();
        if (thread_id < i && thread_id + i < threads) {
#pragma unroll
            for (int n = 0; n < 6; ++n) {
                reduce[n*threads] += reduce[n*threads+i];
            }
        }
    }
    if (thread_id == 0) {
        int ia = bas[ish*BAS_SLOTS+ATOM_OF];
        int ja = bas[jsh*BAS_SLOTS+ATOM_OF];
        atomicAdd(ejk+ia*3+0, reduce[0*threads]);
        atomicAdd(ejk+ia*3+1, reduce[1*threads]);
        atomicAdd(ejk+ia*3+2, reduce[2*threads]);
        atomicAdd(ejk+ja*3+0, reduce[3*threads]);
        atomicAdd(ejk+ja*3+1, reduce[4*threads]);
        atomicAdd(ejk+ja*3+2, reduce[5*threads]);
    }
    __syncthreads();
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
}
}


// ---- (3232) shm : 3600 gout over 60 lanes, 4 quartets/block, 60 dd/lane
extern "C" __global__ void __launch_bounds__(240, 1)
ejk_3232(EARGS)
{
    constexpr int NSQ = 4;
    constexpr int GSTRIDE = 60;
    constexpr int NROOTS = 6;
    constexpr int g_size = 225;
    constexpr int PAD = 15;
    constexpr int HEADSZ = (10 + PAD) * NSQ;
    constexpr int threads = NSQ * GSTRIDE;
    __shared__ double s_aij[36], s_iaij[36], s_ajaij[36];
    __shared__ double s_xij[36], s_yij[36], s_zij[36];
    __shared__ double s_cicj[36], s_ai2[36], s_aj2[36];
    __shared__ int ntasks, pair_ij, ish, jsh;
    __shared__ double ri[3], rjri[3];
    extern __shared__ double shared_memory[];
    int sq_id = threadIdx.x;
    int gout_id = threadIdx.y;
    int thread_id = NSQ * gout_id + sq_id;
    int *bas_kl_idx = pool + blockIdx.x * queue_depth;
    int do_j = j_factor != 0.;
    int do_k = k_factor != 0.;
    double *rlrk = shared_memory + sq_id;
    double *Rpq  = shared_memory + NSQ*3 + sq_id;
    double *akl_cache = shared_memory + NSQ*6 + sq_id;
    double *gx = shared_memory + (10 + PAD)*NSQ + sq_id;
    double *rw = shared_memory + (10 + PAD + 3*g_size)*NSQ + sq_id;
    // the reduction buffer sits on top of the 2D integrals and the roots,
    // which are both rebuilt by the next task; it must stay clear of the pad
    double *reduce = shared_memory + HEADSZ + thread_id;
    // the j and k lowering terms read g(j-1) and g(k-1) at a lane-uniform
    // power that may be zero; the multiplier is then zero but the address is
    // still evaluated, so it lands in this zeroed pad instead of out of bounds
    for (int t = thread_id; t < PAD*NSQ; t += threads) {
        shared_memory[10*NSQ + t] = 0.;
    }
    int o_base = gout_id * 6;
    int lb_ = o_base % 6;
    int kb_ = (o_base / 6) % 10;
    int jb_ = o_base / 60;
    int gb[18], jc[18], kc[18];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      jc[0] = c_lex[12+pj+0];
      kc[0] = c_lex[30+pk+0];
      gb[0] = (jc[0]*5 + kc[0]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[1] = c_lex[12+pj+1];
      kc[1] = c_lex[30+pk+1];
      gb[1] = (jc[1]*5 + kc[1]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[2] = c_lex[12+pj+2];
      kc[2] = c_lex[30+pk+2];
      gb[2] = (jc[2]*5 + kc[2]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+1)*3;
      jc[3] = c_lex[12+pj+0];
      kc[3] = c_lex[30+pk+0];
      gb[3] = (jc[3]*5 + kc[3]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[12+pj+1];
      kc[4] = c_lex[30+pk+1];
      gb[4] = (jc[4]*5 + kc[4]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[12+pj+2];
      kc[5] = c_lex[30+pk+2];
      gb[5] = (jc[5]*5 + kc[5]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+2)*3;
      jc[6] = c_lex[12+pj+0];
      kc[6] = c_lex[30+pk+0];
      gb[6] = (jc[6]*5 + kc[6]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[12+pj+1];
      kc[7] = c_lex[30+pk+1];
      gb[7] = (jc[7]*5 + kc[7]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[8] = c_lex[12+pj+2];
      kc[8] = c_lex[30+pk+2];
      gb[8] = (jc[8]*5 + kc[8]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+3)*3;
      jc[9] = c_lex[12+pj+0];
      kc[9] = c_lex[30+pk+0];
      gb[9] = (jc[9]*5 + kc[9]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[10] = c_lex[12+pj+1];
      kc[10] = c_lex[30+pk+1];
      gb[10] = (jc[10]*5 + kc[10]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[11] = c_lex[12+pj+2];
      kc[11] = c_lex[30+pk+2];
      gb[11] = (jc[11]*5 + kc[11]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+4)*3;
      jc[12] = c_lex[12+pj+0];
      kc[12] = c_lex[30+pk+0];
      gb[12] = (jc[12]*5 + kc[12]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[13] = c_lex[12+pj+1];
      kc[13] = c_lex[30+pk+1];
      gb[13] = (jc[13]*5 + kc[13]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[14] = c_lex[12+pj+2];
      kc[14] = c_lex[30+pk+2];
      gb[14] = (jc[14]*5 + kc[14]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+5)*3;
      jc[15] = c_lex[12+pj+0];
      kc[15] = c_lex[30+pk+0];
      gb[15] = (jc[15]*5 + kc[15]*15 + c_lex[12+pl+0]*75)*NSQ + 0*g_size*NSQ;
      jc[16] = c_lex[12+pj+1];
      kc[16] = c_lex[30+pk+1];
      gb[16] = (jc[16]*5 + kc[16]*15 + c_lex[12+pl+1]*75)*NSQ + 1*g_size*NSQ;
      jc[17] = c_lex[12+pj+2];
      kc[17] = c_lex[30+pk+2];
      gb[17] = (jc[17]*5 + kc[17]*15 + c_lex[12+pl+2]*75)*NSQ + 2*g_size*NSQ;
    }
    if (thread_id == 0) {
        pair_ij = atomicAdd(head, 1);
    }
    __syncthreads();
while (pair_ij < npairs_ij) {
    int bas_ij = pair_ij_mapping[pair_ij];
    if (thread_id == 0) {
        ntasks = 0;
        ish = bas_ij / nbas;
        jsh = bas_ij % nbas;
    }
    __syncthreads();
    fill_ejk_tasks(&ntasks, bas_kl_idx, bas_ij, nbas, pair_kl_mapping,
                   npairs_kl, q_cond, dm_cond, cutoff, do_j, do_k);
    if (ntasks == 0) {
        if (thread_id == 0) { pair_ij = atomicAdd(head, 1); }
        __syncthreads();
        continue;
    }
    if (thread_id < 3) {
        int ri_ptr = bas[ish*BAS_SLOTS+PTR_BAS_COORD];
        int rj_ptr = bas[jsh*BAS_SLOTS+PTR_BAS_COORD];
        ri[thread_id] = env[ri_ptr+thread_id];
        rjri[thread_id] = env[rj_ptr+thread_id] - ri[thread_id];
    }
    __syncthreads();
    int iprim = iprim_a, jprim = jprim_a;
    {
        const double *expi = env + bas[ish*BAS_SLOTS+PTR_EXP];
        const double *expj = env + bas[jsh*BAS_SLOTS+PTR_EXP];
        const double *ci = env + bas[ish*BAS_SLOTS+PTR_COEFF];
        const double *cj = env + bas[jsh*BAS_SLOTS+PTR_COEFF];
        double rr_ij = rjri[0]*rjri[0] + rjri[1]*rjri[1] + rjri[2]*rjri[2];
        for (int ij = thread_id; ij < iprim*jprim; ij += threads) {
            double ai = expi[ij/jprim];
            double aj = expj[ij%jprim];
            double aij = ai + aj;
            double iaij = 1. / aij;
            double aj_aij = aj * iaij;
            s_aij[ij] = aij;  s_iaij[ij] = iaij;  s_ajaij[ij] = aj_aij;
            s_ai2[ij] = ai + ai;  s_aj2[ij] = aj + aj;
            s_xij[ij] = ri[0] + rjri[0] * aj_aij;
            s_yij[ij] = ri[1] + rjri[1] * aj_aij;
            s_zij[ij] = ri[2] + rjri[2] * aj_aij;
            s_cicj[ij] = ci[ij/jprim] * cj[ij%jprim] * exp(-ai * aj_aij * rr_ij);
        }
    }
    __syncthreads();
    double rjri0 = rjri[0], rjri1 = rjri[1], rjri2 = rjri[2];
    double v_ix = 0, v_iy = 0, v_iz = 0, v_jx = 0, v_jy = 0, v_jz = 0;
    int kprim = kprim_a, lprim = lprim_a;

    for (int task_id = sq_id; task_id < ntasks+sq_id; task_id += NSQ) {
        __syncthreads();
        int bas_kl = bas_kl_idx[task_id];
        int ksh = bas_kl / nbas;
        int lsh = bas_kl % nbas;
        double fac_sym = PI_FAC;
        if (task_id < ntasks) {
            if (ish == jsh) fac_sym *= .5;
            if (ksh == lsh) fac_sym *= .5;
            if (bas_ij == bas_kl) fac_sym *= .5;
        } else {
            fac_sym = 0;
        }
        const double *rk = env + bas[ksh*BAS_SLOTS+PTR_BAS_COORD];
        const double *rl = env + bas[lsh*BAS_SLOTS+PTR_BAS_COORD];
        if (gout_id == 0) {
            rlrk[0*NSQ] = rl[0] - rk[0];
            rlrk[1*NSQ] = rl[1] - rk[1];
            rlrk[2*NSQ] = rl[2] - rk[2];
        }
        double dd_[60];
        {
            int i0 = ao_loc[ish], j0 = ao_loc[jsh];
            int k0 = ao_loc[ksh], l0 = ao_loc[lsh];
            int jj = j0 + jb_, kk = k0 + kb_, ll_ = l0 + lb_;
            double dfac;
            #pragma unroll
            for (int n = 0; n < 60; ++n) dd_[n] = 0.;
            if (do_k) {
                dfac = fac_sym * k_factor;
                dd_[0] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[1] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[2] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[3] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[4] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[5] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[6] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+6)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+6)]);
                dd_[7] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+7)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+7)]);
                dd_[8] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+8)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+8)]);
                dd_[9] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+0)*nao+(i0+9)] + dm[(jj+0)*nao+(ll_+0)] * dm[(kk+0)*nao+(i0+9)]);
                dd_[10] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[11] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[12] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[13] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[14] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[15] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[16] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+6)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+6)]);
                dd_[17] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+7)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+7)]);
                dd_[18] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+8)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+8)]);
                dd_[19] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+1)*nao+(i0+9)] + dm[(jj+0)*nao+(ll_+1)] * dm[(kk+0)*nao+(i0+9)]);
                dd_[20] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[21] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[22] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[23] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[24] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[25] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[26] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+6)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+6)]);
                dd_[27] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+7)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+7)]);
                dd_[28] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+8)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+8)]);
                dd_[29] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+2)*nao+(i0+9)] + dm[(jj+0)*nao+(ll_+2)] * dm[(kk+0)*nao+(i0+9)]);
                dd_[30] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+0)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+0)]);
                dd_[31] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+1)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+1)]);
                dd_[32] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+2)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+2)]);
                dd_[33] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+3)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+3)]);
                dd_[34] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+4)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+4)]);
                dd_[35] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+5)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+5)]);
                dd_[36] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+6)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+6)]);
                dd_[37] += dfac * (dm[(jj+0)*nao+(kk+0)] * dm[(ll_+3)*nao+(i0+7)] + dm[(jj+0)*nao+(ll_+3)] * dm[(kk+0)*nao+(i0+7)]);
