    double *rw = shared_memory + (10 + PAD + 3*g_size)*NSQ + sq_id;
    // the reduction buffer sits on top of the 2D integrals and the roots,
    // which are both rebuilt by the next task; it must stay clear of the pad
    double *reduce = shared_memory + HEADSZ + thread_id;
    // the j and k lowering terms read g(j-1) and g(k-1) at a lane-uniform
    // power that may be zero; the multiplier is then zero but the address is
    // still evaluated, so it lands in this zeroed pad instead of out of bounds
    for (int t = thread_id; t < PAD*NSQ; t += threads) {
        shared_memory[10*NSQ + t] = 0.;
    }
    int o_base = gout_id * 3;
    int lb_ = o_base % 3;
    int kb_ = (o_base / 3) % 3;
    int jb_ = o_base / 9;
    int gb[9], jc[9], kc[9];
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+0)*3;
      jc[0] = c_lex[30+pj+0];
      kc[0] = c_lex[3+pk+0];
      gb[0] = (jc[0]*5 + kc[0]*20 + c_lex[3+pl+0]*60)*NSQ + 0*g_size*NSQ;
      jc[1] = c_lex[30+pj+1];
      kc[1] = c_lex[3+pk+1];
      gb[1] = (jc[1]*5 + kc[1]*20 + c_lex[3+pl+1]*60)*NSQ + 1*g_size*NSQ;
      jc[2] = c_lex[30+pj+2];
      kc[2] = c_lex[3+pk+2];
      gb[2] = (jc[2]*5 + kc[2]*20 + c_lex[3+pl+2]*60)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+1)*3;
      jc[3] = c_lex[30+pj+0];
      kc[3] = c_lex[3+pk+0];
      gb[3] = (jc[3]*5 + kc[3]*20 + c_lex[3+pl+0]*60)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[30+pj+1];
      kc[4] = c_lex[3+pk+1];
      gb[4] = (jc[4]*5 + kc[4]*20 + c_lex[3+pl+1]*60)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[30+pj+2];
      kc[5] = c_lex[3+pk+2];
      gb[5] = (jc[5]*5 + kc[5]*20 + c_lex[3+pl+2]*60)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+2)*3;
      jc[6] = c_lex[30+pj+0];
      kc[6] = c_lex[3+pk+0];
      gb[6] = (jc[6]*5 + kc[6]*20 + c_lex[3+pl+0]*60)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[30+pj+1];
      kc[7] = c_lex[3+pk+1];
      gb[7] = (jc[7]*5 + kc[7]*20 + c_lex[3+pl+1]*60)*NSQ + 1*g_size*NSQ;
      jc[8] = c_lex[30+pj+2];
      kc[8] = c_lex[3+pk+2];
      gb[8] = (jc[8]*5 + kc[8]*20 + c_lex[3+pl+2]*60)*NSQ + 2*g_size*NSQ;
