                for (int irys = 0; irys < NROOTS; ++irys) {
                    __syncthreads();
                    double s0, s1, s2;
                    double rt = rw[2*irys*NSQ];
                    double rt_aa = rt * inv_s2;
                    double rt_aij = rt_aa * akl;
                    double rt_akl = rt_aa * aij;
                    double b10 = .5*iaij * (1 - rt_aij);
                    double b00 = .5 * rt_aa;
                    double b01 = .5*iakl * (1 - rt_akl);
                    (void)b10; (void)b00; (void)b01; (void)s2;
                    for (int n = gout_id; n < 3; n += GSTRIDE) {
                        if (n == 2) { gx[2*g_size*NSQ] = rw[(2*irys+1)*NSQ]; }
                        double *_gx = gx + n * g_size * NSQ;
                        double xjxi = rjri[n], xlxk = rlrk[n*NSQ];
                        double c0x = xjxi * s_ajaij[ijp] - rt_aij * Rpq[n*NSQ];
                        double cpx = xlxk * al_akl + rt_akl * Rpq[n*NSQ];
                        (void)c0x; (void)cpx; (void)xjxi; (void)xlxk;
                        s0 = _gx[0*NSQ];
                        s1 = c0x * s0;
                        _gx[1*NSQ] = s1;
                        s2 = c0x * s1 + 1 * b10 * s0;
                        _gx[2*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 2 * b10 * s0;
                        _gx[3*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 3 * b10 * s0;
                        _gx[4*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 4 * b10 * s0;
                        _gx[5*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 5 * b10 * s0;
                        _gx[6*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = c0x * s1 + 6 * b10 * s0;
                        _gx[7*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[0*NSQ];
                        s1 = cpx * s0;
                        _gx[20*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        _gx[40*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s2 = cpx * s1 + 2 * b01 * s0;
                        _gx[60*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
                        s0 = _gx[1*NSQ];
                        s1 = cpx * s0;
                        s1 += 1 * b00 * _gx[0*NSQ];
                        _gx[21*NSQ] = s1;
                        s2 = cpx * s1 + 1 * b01 * s0;
                        s2 += 1 * b00 * _gx[20*NSQ];
                        _gx[41*NSQ] = s2;
                        s0 = s1;
                        s1 = s2;
