                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[7]) * gm2_1[-5*NSQ];
                    fyk = ak2 * gm2_1[20*NSQ] - (kc[7]) * gm2_1[-20*NSQ];
                    v_iy += fyi * pxz;
                    v_jy += fyj * pxz;
                    v_ky += fyk * pxz;
                    v_ly -= (fyi + fyj + fyk) * pxz;
                    giz = gm2_2[3*NSQ];
                    fzi = ai2 * giz - 2 * gm2_2[1*NSQ];
                    fzj = aj2 * (giz - rjri2 * Iz) - (jc[8]) * gm2_2[-3*NSQ];
                    fzk = ak2 * gm2_2[22*NSQ] - (kc[8]) * gm2_2[-18*NSQ];
                    v_iz += fzi * pxy;
                    v_jz += fzj * pxy;
                    v_kz += fzk * pxy;
                    v_lz -= (fzi + fzj + fzk) * pxy;
                    dd = dd_[26];
                    Ix = gm2_0[0*NSQ];
                    Iy = gm2_1[3*NSQ];
