                    v_lx -= (fxi + fxj + fxk) * pyz;
                    giy = gm2_1[4*NSQ];
                    fyi = ai2 * giy - 3 * gm2_1[2*NSQ];
                    fyj = aj2 * (giy - rjri1 * Iy) - (jc[7]) * gm2_1[-2*NSQ];
