                    pxz = Ix * Iz * dd;
                    pyz = Iy * Iz * dd;
                    gix = gm2_0[1*NSQ];
                    fxi = ai2 * gix;
                    fxj = aj2 * (gix - rjri0 * Ix) - (jc[6]) * gm2_0[-5*NSQ];
                    fxk = ak2 * gm2_0[20*NSQ] - (kc[6]) * gm2_0[-20*NSQ];
