                dd_[35] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+5)]);
                dd_[36] += dfac * (dm[(ll_+0)*nao+(kk+3)] * dm[(jj+0)*nao+(i0+6)]);
