                dd_[44] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+4)]);
                dd_[45] += dfac * (dm[(ll_+0)*nao+(kk+4)] * dm[(jj+0)*nao+(i0+5)]);
