      kc[3] = c_lex[30+pk+0];
      gb[3] = (jc[3]*5 + kc[3]*20 + c_lex[30+pl+0]*100)*NSQ + 0*g_size*NSQ;
      jc[4] = c_lex[30+pj+1];
      kc[4] = c_lex[30+pk+1];
      gb[4] = (jc[4]*5 + kc[4]*20 + c_lex[30+pl+1]*100)*NSQ + 1*g_size*NSQ;
      jc[5] = c_lex[30+pj+2];
      kc[5] = c_lex[30+pk+2];
      gb[5] = (jc[5]*5 + kc[5]*20 + c_lex[30+pl+2]*100)*NSQ + 2*g_size*NSQ;
    }
    { int pj = (jb_+0)*3, pk = (kb_+0)*3, pl = (lb_+2)*3;
      jc[6] = c_lex[30+pj+0];
      kc[6] = c_lex[30+pk+0];
      gb[6] = (jc[6]*5 + kc[6]*20 + c_lex[30+pl+0]*100)*NSQ + 0*g_size*NSQ;
      jc[7] = c_lex[30+pj+1];
      kc[7] = c_lex[30+pk+1];
      gb[7] = (jc[7]*5 + kc[7]*20 + c_lex[30+pl+1]*100)*NSQ + 1*g_size*NSQ;
